import Foundation
// Module "Croc" is generated by gomobile (Croc.xcframework) from go/crocmobile; see scripts/build-croc-framework.sh.
import Croc

/// The only file that talks to the Go library. If Xcode reports that the
/// generated Crocmobile* names differ, adjust the calls here.
enum CrocBridge {
    /// Empty means "automatic": the relay is derived from the code, as other croc clients do.
    static let defaultRelay = ""

    static func generateCode() throws -> String {
        var err: NSError?
        let code = CrocmobileGenerateCode(&err)
        if let err { throw err }
        return code
    }

    /// Sends the given local files. Blocks until the transfer ends, so call it off the main thread.
    static func send(files: [URL], code: String, relay: String, relayPassword: String) throws {
        let paths = files.map { $0.path }.joined(separator: "\n")
        var err: NSError?
        CrocmobileSend(paths, code, relay, relayPassword, &err)
        if let err { throw err }
    }

    /// Sends a text message. Blocks until the transfer ends, so call it off the main thread.
    static func sendText(_ text: String, code: String, relay: String, relayPassword: String) throws {
        var err: NSError?
        CrocmobileSendText(text, code, relay, relayPassword, &err)
        if let err { throw err }
    }

    /// Receives into `destination`. Returns the message when the sender sent text, otherwise
    /// nil (files were saved). Blocks until the transfer ends, so call it off the main thread.
    static func receive(code: String, relay: String, relayPassword: String, destination: URL) throws -> String? {
        var err: NSError?
        let text = CrocmobileReceive(code, relay, relayPassword, destination.path, &err)
        if let err { throw err }
        return text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty ? nil : text
    }

    static func isValidSSHCode(_ code: String) -> Bool {
        CrocmobileValidSSHCode(code)
    }

    /// A joined shared terminal.
    struct SSHHandle {
        let sendInput: (Data) -> Void
        let close: () -> Void
    }

    /// Joins a shared terminal. Returns at once; output arrives through `sink`.
    static func joinSSH(code: String, relay: String, relayPassword: String, cols: Int, rows: Int,
                        sink: CrocmobileTerminalSink) throws -> SSHHandle {
        var err: NSError?
        let session = CrocmobileJoinSSH(code, relay, relayPassword, cols, rows, sink, &err)
        if let err { throw err }
        guard let session else { throw NSError(domain: "croc", code: 1, userInfo: [NSLocalizedDescriptionKey: "Could not join."]) }
        return SSHHandle(sendInput: { session.sendInput($0) }, close: { session.close() })
    }

    /// True when the receiver turned the transfer down (not a failure).
    static func isDeclined(_ error: Error) -> Bool {
        (error as NSError).localizedDescription.contains("declined by the receiver")
    }
}
